function badge(label,msg,color){color=color||'5E6AD2';return '![('+label+'-'+msg+'-'+color+')](https://img.shields.io/badge/'+encodeURIComponent(label)+'-'+encodeURIComponent(msg)+'-'+color+')';}
function genReadme(o){
  var L=[];L.push('# '+o.name);L.push('');
  if(o.desc)L.push(o.desc);L.push('');
  L.push('## 特性');L.push('');
  (o.features&&o.features.length?o.features:['- 单文件 HTML，零依赖，打开即用','- 数据全程留在本机，不上传任何服务器','- 支持 PWA 安装与离线使用']).forEach(function(f){L.push(f);});
  L.push('');
  var badges=[];badges.push(badge('license',o.license||'MIT','blue'));badges.push(badge('status',o.status||'stable','green'));badges.push(badge('deps','zero','lightgrey'));
  L.push(badges.join('  '));L.push('');
  L.push('## 安装');L.push('');L.push('直接用浏览器打开 `index.html` 即可。');L.push('');
  L.push('## 许可');L.push('');L.push('MIT © '+(o.author||'you'));L.push('');
  return L.join('\n');
}
var EXPORTS={genReadme:genReadme,badge:badge};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ReadmeForgePure = EXPORTS; }
